/** Vertical metrics, as a ratio of font size, from the 400 face. */
export const VERTICAL = {
  ascent: 0.712,
  descent: 0.205,
  capHeight: 0.656,
} as const;

/** Fallback advance for a character outside the table — lowercase `n`. */
const FALLBACK = 0.547;

/** Width of `text` at `size`, in px. */
export function measureText(text: string, size: number, weight = 400): number {
  const row = ADVANCE[weight] ?? ADVANCE[400];
  let total = 0;
  for (const ch of text) total += row[ch] ?? FALLBACK;
  return total * size;
}

/** The line box a run of text occupies. */
export function textBox(text: string, size: number, weight = 400) {
  return {
    width: measureText(text, size, weight),
    height: (VERTICAL.ascent + VERTICAL.descent) * size,
    /** Baseline offset from the top of the line box. */
    baseline: VERTICAL.ascent * size,
  };
}
